SELECT 'https://example.org/oulad/id/offering/' || code_module || '/' || code_presentation AS offering, 'https://example.org/oulad/id/assessment/' || id_assessment AS assessment, 'https://example.org/oulad/schema#' || CASE assessment_type WHEN 'TMA' THEN 'TutorMarkedAssessment' WHEN 'CMA' THEN 'ComputerMarkedAssessment' ELSE 'Exam' END AS type, deadline_day AS deadline, weight FROM assessments;
